/**
 * Returns a presigned GCS URL for direct upload. The client sends JSON
 * metadata here, then uploads the file directly to the returned URL.
 * @summary Request a presigned URL for file upload
 */

export const requestUploadUrlBodySizeMax = 10485760;




export const RequestUploadUrlBody = zod.object({
  "name": zod.string().min(1).describe('Original file name.'),
  "size": zod.number().int().min(1).max(requestUploadUrlBodySizeMax).describe('File size in bytes (max 10 MB).'),
  "contentType": zod.string().min(1).describe('MIME type of the file (e.g. `image/jpeg`).')
})


export const requestUploadUrlResponseMetadataSizeMax = 10485760;




export const RequestUploadUrlResponse = zod.object({
  "uploadURL": zod.string().describe('URL for the PUT upload (may be a server-proxied endpoint).'),
  "objectPath": zod.string().describe('Normalized object path (e.g. `/objects/uploads/uuid`). Store this in your database.'),
  "metadata": zod.object({
  "name": zod.string().min(1).describe('Original file name.'),
  "size": zod.number().int().min(1).max(requestUploadUrlResponseMetadataSizeMax).describe('File size in bytes (max 10 MB).'),
  "contentType": zod.string().min(1).describe('MIME type of the file (e.g. `image/jpeg`).')
}).optional()
})


